#include <cstdio>
#include <algorithm>

using namespace std;

int main()
{
    long long n = 0, m = 0;
    scanf("%lld%lld", &n, &m);

    long long s = n + m;
    long long l = 1, r = 0, ans = 0;

    while (l <= s)
    {
        r = s / (s / l);
        long long g = s / l;

        if (n < g || m < g)
        {
            l = r + 1;
            continue;
        }

        long long l1 = (n + g) / (g + 1);
        long long r1 = n / g;
        long long l2 = (m + g) / (g + 1);
        long long r2 = m / g;

        if (r1 >= l1 && r2 >= l2)
        {
            ans += max(min(r1 + r2, r) - max(l1 + l2, l) + 1, 0LL);
        }

        l = r + 1;
    }

    printf("%lld", ans);
    return 0;
}

